        for each subset S of the vertices with |S| = size:
            if no edge of G lies inside S:
                return size
    return 0

function independence_ratio(G):
    return Fraction(independence_number(G), n)

function fractional_chromatic_lower_bound(G):
    return Fraction(n, independence_number(G))   # n / alpha(G)

function forces_plane_above_four(G):
    return independence_ratio(G) < 1/4           # => chi_f(R^2) > 4

